/* From Uiverse.io by cbolson  - Tags: radio */
/* From Uiverse.io by cbolson */
.__UIV_SCOPE__ .my-form {
  --_clr-primary: #666;
  --_clr-hover: #f33195;
  --_clr-checked: #127acf;
}
.__UIV_SCOPE__ .my-form > div {
  --_clr-current: var(--_clr-primary);

  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.__UIV_SCOPE__ .my-form > div + div {
  margin-block-start: 0.5rem;
}
.__UIV_SCOPE__ .my-form label {
  cursor: pointer;
  color: var(--_clr-current);
  transition: color 150ms ease-in-out;
}
/* styled radio */
.__UIV_SCOPE__ .my-form input[type="radio"] {
  appearance: none;
  outline: none;
  width: 1.5rem;
  height: 1.5rem;
  aspect-ratio: 1;
  padding: 0.25rem;
  background: transparent;
  border: 1px solid var(--_clr-current);
  border-radius: 50%;
  display: grid;
  place-content: center;
  cursor: pointer;
  position: relative;
}
.__UIV_SCOPE__ .my-form input[type="radio"]::after {
  content: "";
  position: absolute;
  inset: 0.25rem;
  opacity: 0;
  scale: 0;
  transition:
    opacity 150ms ease-in-out,
    scale 150ms ease-in-out;
  background-color: var(--_clr-checked);
  border-radius: inherit;
}

.__UIV_SCOPE__ .my-form label:hover,
.__UIV_SCOPE__ .my-form input[type="radio"]:focus-visible,
.__UIV_SCOPE__ .my-form input[type="radio"]:focus-visible + label,
.__UIV_SCOPE__ .my-form input[type="radio"]:hover,
.__UIV_SCOPE__ .my-form input[type="radio"]:hover + label {
  --_clr-current: var(--_clr-hover);
}
.__UIV_SCOPE__ .my-form input[type="radio"]:focus-visible::after,
.__UIV_SCOPE__ .my-form input[type="radio"]:hover::after {
  opacity: 0.5;
  scale: 1;
  background-color: var(--_clr-hover);
}

.__UIV_SCOPE__ .my-form input[type="radio"]:checked + label:not(:hover),
.__UIV_SCOPE__ .my-form input[type="radio"]:checked:not(:hover) {
  --_clr-current: var(--_clr-checked);
}
.__UIV_SCOPE__ .my-form input[type="radio"]:checked::after {
  opacity: 1;
  scale: 1;
}
